/* Sample only unoccupied sea/sky; original product, labels and wood never move. */
(()=>{const host=document.querySelector('.coastal-art');if(!host)return;const photo=host.querySelector('img'),canvas=host.querySelector('canvas'),ctx=canvas.getContext('2d'),button=host.querySelector('button'),reduce=matchMedia('(prefers-reduced-motion: reduce)');const size=768;const layer=document.createElement('canvas');layer.width=layer.height=size;const paint=layer.getContext('2d');const mask=document.createElement('canvas');mask.width=mask.height=size;const m=mask.getContext('2d');let paused=false,visible=false,frame=0,last=0;
for(const [x,y,w,h] of [[0,.148,.255,.19],[.755,.148,.245,.19],[0,0,1,.075]]){const g=m.createLinearGradient(0,y*size,0,(y+h)*size);g.addColorStop(0,'transparent');g.addColorStop(.22,'white');g.addColorStop(.76,'white');g.addColorStop(1,'transparent');m.fillStyle=g;m.fillRect(x*size,y*size,w*size,h*size);}m.globalCompositeOperation='destination-in';const edge=m.createLinearGradient(0,0,size,0);for(const [stop,a]of [[0,1],[.21,1],[.255,0],[.745,0],[.785,1],[1,1]])edge.addColorStop(stop,`rgba(255,255,255,${a})`);m.fillStyle=edge;m.fillRect(0,0,size,size);
function draw(t){frame=0;if(paused||reduce.matches||document.hidden||!visible)return;frame=requestAnimationFrame(draw);if(t-last<40||!photo.complete||!photo.naturalWidth)return;last=t;paint.clearRect(0,0,size,size);const sec=t/1000;for(let y=0;y<size*.34;y+=2){const water=y>size*.14;const dx=water?Math.sin(y*.05-sec*1.5)*16:Math.sin(sec*.17)*9;const dy=water?Math.sin(y*.033-sec*1.2)*5:0;paint.drawImage(photo,0,(y+dy)/size*photo.naturalHeight,photo.naturalWidth,2/size*photo.naturalHeight,dx,y,size,2);}paint.globalCompositeOperation='destination-in';paint.drawImage(mask,0,0);paint.globalCompositeOperation='source-over';ctx.clearRect(0,0,size,size);ctx.drawImage(layer,0,0);canvas.dataset.frames=String(+(canvas.dataset.frames||0)+1);}
function sync(){cancelAnimationFrame(frame);frame=0;button.textContent=reduce.matches?'Still scene':paused?'Play scene':'Pause scene';button.disabled=reduce.matches;button.setAttribute('aria-pressed',String(paused));canvas.hidden=reduce.matches||paused;if(!paused&&!reduce.matches&&!document.hidden&&visible)frame=requestAnimationFrame(draw);}
button.addEventListener('click',()=>{paused=!paused;sync();});new IntersectionObserver(es=>{visible=es[0].isIntersecting;sync();}).observe(host);reduce.addEventListener('change',sync);document.addEventListener('visibilitychange',sync);addEventListener('pagehide',()=>cancelAnimationFrame(frame));photo.addEventListener('load',sync);sync();})();
